import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Luật Đảm bảo Y tế","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0044-医疗保障法.md","filePath":"vi/0044-医疗保障法.md"}'),u={name:"vi/0044-医疗保障法.md"};function g(a,n,l,o,r,p){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="luat-đam-bao-y-te" tabindex="-1">Luật Đảm bảo Y tế <a class="header-anchor" href="#luat-đam-bao-y-te" aria-label="Permalink to &quot;Luật Đảm bảo Y tế&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>44</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Quyền y tế, y tế cộng sinh, điều trị chấn thương tu luyện, sức khỏe sự sống, hệ thống bảo hiểm y tế</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Đảm bảo Y tế》 là một trong năm luật pháp hỗ trợ của văn minh cộng sinh neo, nhằm đảm bảo quyền sức khỏe và quyền y tế của mọi sự sống bên trong Hengyuanzhou, xây dựng hệ thống y tế cộng sinh bao phủ mọi tộc, và đảm bảo mỗi sự sống khi bị ốm hoặc thương đều có thể nhận được điều trị kịp thời, hiệu quả.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc ưu tiên sức khỏe</td><td>Sức khỏe sự sống là nền tảng của mọi tiến hóa, nhà nước và văn minh đặt việc đảm bảo sức khỏe sự sống vào vị trí ưu tiên</td></tr><tr><td>Nguyên tắc bao phủ phổ quát</td><td>Đảm bảo y tế bao phủ mọi sự sống, bất kể tộc, trình độ tu luyện, xuất thân và tình hình kinh tế</td></tr><tr><td>Nguyên tắc chẩn đoán phân cấp</td><td>Xây dựng hệ thống chẩn đoán ba cấp: y tế cơ sở, y tế khu vực, y tế cao cấp, phân bổ hợp lý nguồn lực y tế</td></tr><tr><td>Nguyên tắc kết hợp phòng ngừa và điều trị</td><td>Phòng ngừa là chính, kết hợp phòng ngừa và điều trị, coi trọng phòng ngừa và phục hồi chức năng chấn thương tu luyện</td></tr><tr><td>Nguyên tắc thích ứng liên tộc</td><td>Cung cấp kế hoạch y tế thích ứng với đặc điểm sinh lý của các tộc khác nhau, cấm sử dụng tiêu chuẩn người tộc một cách đồng bộ</td></tr><tr><td>Nguyên tắc thuộc tính phúc lợi công cộng</td><td>Dịch vụ y tế cơ bản có thuộc tính phúc lợi công cộng, không được vì mục đích lợi nhuận mà tước đoạt quyền điều trị của sự sống</td></tr></tbody></table><h2 id="_2-đam-bao-phap-luat-ve-quyen-suc-khoe-su-song" tabindex="-1">2. Đảm bảo pháp luật về quyền sức khỏe sự sống <a class="header-anchor" href="#_2-đam-bao-phap-luat-ve-quyen-suc-khoe-su-song" aria-label="Permalink to &quot;2. Đảm bảo pháp luật về quyền sức khỏe sự sống&quot;">​</a></h2><p>Luật này quy định rõ ràng rằng quyền sức khỏe sự sống là quyền cơ bản được Hiến pháp Cộng sinh trao cho mỗi sự sống, cụ thể bao gồm:</p><ol><li><strong>Quyền y tế cơ bản</strong>: Mỗi sự sống có quyền nhận dịch vụ y tế cơ bản miễn phí, bao gồm chẩn đoán và điều trị bệnh thông thường, thuốc cơ bản, khám sức khỏe định kỳ, v.v.</li><li><strong>Quyền điều trị cấp cứu</strong>: Mỗi sự sống khi bị bệnh hoặc thương đột ngột có quyền nhận điều trị khẩn cấp, và cơ sở y tế không được từ chối điều trị cấp cứu với bất kỳ lý do gì.</li><li><strong>Quyền điều trị chấn thương tu luyện</strong>: Người tu luyện khi bị các chấn thương như rối loạn năng lượng, tổn thương kinh lạc, đi hỏa nhập ma, v.v. trong quá trình tu luyện có quyền nhận điều trị chuyên môn.</li><li><strong>Quyền đồng ý có thông tin</strong>: Bệnh nhân có quyền biết tình trạng bệnh của mình, kế hoạch điều trị, rủi ro và tiên lượng, và có quyền lựa chọn hoặc từ chối kế hoạch điều trị.</li><li><strong>Quyền bảo vệ quyền riêng tư</strong>: Thông tin y tế và dữ liệu cơ thể của bệnh nhân được pháp luật bảo vệ, không được tiết lộ hoặc sử dụng cho mục đích khác mà không có sự đồng ý của bệnh nhân.</li><li><strong>Quyền đảm bảo phục hồi chức năng</strong>: Bệnh nhân bị ốm hoặc thương có quyền nhận điều trị phục hồi chức năng và thiết bị hỗ trợ, giúp họ phục hồi khả năng lao động và sinh hoạt.</li></ol><h2 id="_3-co-cau-he-thong-y-te-cong-sinh" tabindex="-1">3. Cơ cấu hệ thống y tế cộng sinh <a class="header-anchor" href="#_3-co-cau-he-thong-y-te-cong-sinh" aria-label="Permalink to &quot;3. Cơ cấu hệ thống y tế cộng sinh&quot;">​</a></h2><p>Hệ thống y tế của văn minh cộng sinh neo được chia thành ba cấp, giữa các cấp đã thiết lập cơ chế giới thiệu và hợp tác:</p><table tabindex="0"><thead><tr><th>Cấp</th><th>Tên</th><th>Chức năng</th><th>Phạm vi bao phủ</th></tr></thead><tbody><tr><td>Cấp thứ nhất</td><td>Trạm y tế cơ sở</td><td>Chẩn đoán và điều trị bệnh thông thường, phòng ngừa và chăm sóc sức khỏe, khám sức khỏe cơ bản, vận chuyển cấp cứu</td><td>Cộng đồng/làng/bidang nhỏ</td></tr><tr><td>Cấp thứ hai</td><td>Trung tâm y tế khu vực</td><td>Chẩn đoán chuyên khoa, điều trị phẫu thuật, xử lý ban đầu chấn thương tu luyện, phục hồi chức năng</td><td>Thành phố/khu vực/bidang trung bình</td></tr><tr><td>Cấp thứ ba</td><td>Bệnh viện tổng hợp y tế cao cấp</td><td>Bệnh nan trọng, chấn thương tu luyện cao cấp, bệnh lĩnh vực ý thức, bệnh nan liên tộc</td><td>Cốt lõi văn minh/bidang lớn</td></tr></tbody></table><p>Ngoài ra, &quot;Khoa chuyên môn chấn thương tu luyện&quot; được thành lập: chuyên biệt xử lý các loại chấn thương trong quá trình tu luyện, bao gồm quá tải năng lượng, đứt gãy kinh lạc, xâm nhập tâm ma, tổn thương linh hồn, v.v., được trang bị nhân viên y tế thành thạo quy luật tu luyện.</p><h2 id="_4-quy-đam-bao-y-te" tabindex="-1">4. Quỹ đảm bảo y tế <a class="header-anchor" href="#_4-quy-đam-bao-y-te" aria-label="Permalink to &quot;4. Quỹ đảm bảo y tế&quot;">​</a></h2><p>Quỹ đảm bảo y tế là nền tảng kinh tế cho hoạt động của hệ thống y tế cộng sinh, và nguồn gốc của nó bao gồm:</p><ul><li>Cấp phát từ tích lũy công cộng (nguồn chính)</li><li>Khoản trích đảm bảo y tế trong cơ chế hợp đồng sản xuất liên hợp</li><li>Quyên góp xã hội</li><li>Thu nhập đầu tư của quỹ</li></ul><p>Phạm vi thanh toán của quỹ bao gồm: chi phí dịch vụ y tế cơ bản, chi phí cấp cứu, chi phí điều trị chấn thương tu luyện, chi phí thuốc cơ bản, chi phí phục hồi chức năng, v.v. Bệnh nhân cá nhân chỉ cần thanh toán một khoản chi phí tự trả nhỏ, và đối với người gặp khó khăn kinh tế thì thực hiện giảm miễn.</p><h2 id="_5-co-so-y-te-va-nhan-vien-y-te" tabindex="-1">5. Cơ sở y tế và nhân viên y tế <a class="header-anchor" href="#_5-co-so-y-te-va-nhan-vien-y-te" aria-label="Permalink to &quot;5. Cơ sở y tế và nhân viên y tế&quot;">​</a></h2><ul><li><strong>Cơ sở y tế công lập</strong>: Do nhà nước hoặc cộng đồng văn minh thành lập, chịu trách nhiệm dịch vụ y tế cơ bản và chức năng y tế công cộng, kinh phí được đảm bảo bởi quỹ đảm bảo y tế.</li><li><strong>Cơ sở y tế tư nhân</strong>: Do lực lượng xã hội thành lập theo pháp luật, có thể cung cấp dịch vụ y tế cao cấp, nhưng phải接受 sự giám sát của部门主管 y tế, và không được từ chối bệnh nhân cấp cứu.</li><li><strong>Cơ sở y tế liên tộc</strong>: Cơ sở y tế chuyên khoa thành lập cho nhu cầu sinh lý của tộc đặc biệt, được trang bị nhân viên y tế tộc khác.</li><li><strong>Quyền và nghĩa vụ của nhân viên y tế</strong>: Nhân viên y tế được hưởng các quyền như bảo vệ hành nghề, thù lao hợp lý, đào tạo nghề, v.v., đồng thời có nghĩa vụ cứu thương cứu bệnh, tôn trọng bệnh nhân, giữ bí mật y tế, v.v.</li></ul><h2 id="_6-y-te-cong-cong-va-phong-ngua" tabindex="-1">6. Y tế công cộng và phòng ngừa <a class="header-anchor" href="#_6-y-te-cong-cong-va-phong-ngua" aria-label="Permalink to &quot;6. Y tế công cộng và phòng ngừa&quot;">​</a></h2><p>Nhà nước xây dựng hệ thống y tế công cộng, thực hiện các chức năng sau:</p><ol><li>Giám sát và phòng chống dịch bệnh truyền nhiễm, xây dựng cơ chế cảnh báo dịch bệnh liên位面.</li><li>Khám sức khỏe toàn dân và quản lý hồ sơ sức khỏe.</li><li>Tuyên truyền an toàn tu luyện và hướng dẫn phòng ngừa chấn thương tu luyện.</li><li>Giám sát sức khỏe môi trường và an toàn thực phẩm, dược phẩm.</li><li>Ứng phó khẩn cấp với sự kiện y tế công cộng đột ngột.</li></ol><h2 id="_7-trach-nhiem-phap-ly" tabindex="-1">7. Trách nhiệm pháp lý <a class="header-anchor" href="#_7-trach-nhiem-phap-ly" aria-label="Permalink to &quot;7. Trách nhiệm pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ul><li>Cơ sở y tế từ chối bệnh nhân cấp cứu, ra lệnh khắc phục và phạt tiền, gây ra hậu quả nghiêm trọng thì thu hồi giấy phép hành nghề.</li><li>Nhân viên y tế vì thiếu trách nhiệm nghiêm trọng gây tổn hại cho bệnh nhân, chịu trách nhiệm bồi thường, trường hợp nghiêm trọng thì thu hồi tư cách hành nghề.</li><li>Cơ sở y tế thu phí vi phạm, điều trị quá mức, ra lệnh hoàn trả phí và phạt tiền.</li><li>Tiết lộ quyền riêng tư y tế của bệnh nhân, chịu bồi thường thiệt hại tinh thần, trường hợp nghiêm trọng thì truy cứu trách nhiệm hình sự.</li><li>Sản xuất, bán thuốc giả, thuốc kém chất lượng, tịch thu thu nhập bất hợp pháp và phạt tiền, cấu thành tội phạm thì truy cứu trách nhiệm hình sự.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Đảm bảo Y tế》 là sự thể hiện của khái niệm &quot;mọi người đều có con đường&quot; của văn minh cộng sinh neo trong lĩnh vực sức khỏe. Bằng cách xây dựng hệ thống đảm bảo y tế bao phủ phổ quát, thành lập khoa chuyên môn chấn thương tu luyện, đảm bảo quyền điều trị cấp cứu, nó đảm bảo mỗi sự sống khi bị ốm hoặc thương đều có thể nhận được điều trị kịp thời, và củng cố nền tảng sức khỏe cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>38-共生医疗体系 (Hệ thống Y tế Cộng sinh)</li><li>45-住房保障法 (Luật Đảm bảo Nhà ở)</li><li>08-人人有路保障体系 (Hệ thống Đảm bảo Mọi người đều có Con đường)</li></ul>',29)])])}const s=h(u,[["render",g]]);export{e as __pageData,s as default};
